import {photos,niches,videos,services,gallery,socials} from './content.js';
export const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function photo(key,sizes='(min-width: 900px) 35vw, 80vw',className=''){
 const p=photos[key];
 if(!p)return `<img class="${className}" src="${esc(key)}" alt="" loading="lazy" width="900" height="1200">`;
 return `<img class="${className}" src="/assets/photos/liza-${p.id}-960.webp" srcset="/assets/photos/liza-${p.id}-480.webp 480w, /assets/photos/liza-${p.id}-960.webp 960w, /assets/photos/liza-${p.id}-1440.webp 1440w" sizes="${sizes}" width="900" height="1200" loading="lazy" decoding="async" alt="${esc(p.alt)}">`;
}
const label=(n,name)=>`<p class="eyebrow micro">${n} / ${name}</p>`;
function About(){return `<section class="about section" id="about"><div class="wrap about-grid"><div class="about-heading">${label('01','Обо мне')}<h2>Привет,<br>я Лиза.</h2><p class="handwritten">давайте чуть ближе</p></div><figure class="about-portrait">${photo('summer')}<span class="tape" aria-hidden="true"></span><figcaption class="micro">ИЗ МОЕГО ФОТОДНЕВНИКА</figcaption></figure><div class="about-paper paper"><p class="about-lead">Я Лиза — лайфстайл<br>и UGC-креатор.</p><p>Создаю живой, эстетичный и нативный контент о красоте, стиле, повседневной жизни и маленьких вещах, которые делают её интереснее.</p><p>Мне важно, чтобы реклама не выбивалась из контента, а становилась его естественной частью. Поэтому я стараюсь не просто показать продукт, а придумать историю и подачу, через которые он действительно заинтересует аудиторию.</p><span class="paper-number micro">ЗАМЕТКА 001</span></div><blockquote class="about-quote"><span>Мой стиль — эстетика,<br>естественность,</span><strong class="handwritten">ощущение разговора<br>с подругой.</strong></blockquote></div><div class="bridge-film film" aria-hidden="true">${['beauty','street','cafe','mirror'].map(k=>photo(k,'160px')).join('')}<span class="micro">BEAUTY / FASHION / LIFE</span></div></section>`}
function Contents(){return `<section class="contents section" id="contents"><div class="wrap record-layout"><div class="record-heading">${label('02','Внутри портфолио')}<h2>Поставим<br>на <span class="handwritten">повтор?</span></h2><p>То, что мне близко.<br>И то, что я создаю.</p></div><div class="record-object"><div class="record-sleeve"><span class="micro">ЛИЧНАЯ КОЛЛЕКЦИЯ</span><span class="sleeve-name">Лиза</span><span class="micro">LIFESTYLE / BEAUTY / FASHION</span></div><div class="record-lift"><div class="record-spin"><img class="record" src="/assets/vinyl.webp" width="1100" height="1100" loading="lazy" alt="Розовая виниловая пластинка"><span class="record-mark micro">LIZA<br>SIDE A<br>33⅓ RPM</span></div></div><span class="record-annotation handwritten">каждый кадр —<br>с настроением</span></div><nav class="tracklist" aria-label="Разделы портфолио">${[['about','Обо мне','ЗНАКОМСТВО'],['niches','Направления','МОЙ МИР'],['work','Работы','СМОТРЕТЬ'],['services','Что я создаю','ФОРМАТЫ'],['contact','Контакты','НА СВЯЗИ']].map(([id,name,note],i)=>`<a href="#${id}"><span class="micro">0${i+1}</span><span>${name}</span><small class="micro">${note}</small></a>`).join('')}</nav></div></section>`}
function Niches(){return `<section class="niches section" id="niches"><div class="wrap">${label('03','Мои направления')}<div class="niche-title"><h2>Мои<br>направления.</h2><span class="handwritten">пять маленьких миров</span></div><div class="niche-layout"><div class="niche-cutouts"><figure class="niche-fashion">${photo('mirror')}<figcaption class="micro">FASHION NOTES</figcaption></figure><figure class="niche-beauty">${photo('portrait')}<span class="tape" aria-hidden="true"></span></figure><span class="handwritten niche-note">собираю своё<br>вдохновение</span></div><div class="niche-list">${niches.map((n,i)=>`<article class="niche-row"><span class="micro">0${i+1}</span><div><h3>${n.name}</h3>${n.description?`<p>${esc(n.description)}</p>`:''}</div></article>`).join('')}</div></div></div></section>`}
function Work(){return `<section class="work section" id="work"><div class="wrap">${label('04','Работы / Selected UGC')}<div class="work-heading"><h2>Смотреть.<br>Чувствовать.</h2><p class="handwritten">ещё один кадр,<br>и ещё один…</p></div>${videos.some(v=>!v.src)?'<p class="work-draft">Здесь скоро появятся 12 видео.<br>Пока — кадры Лизы и превью будущих работ.</p>':''}<div class="reels-wall"><div class="wall-label micro">КОНТАКТНЫЙ ЛИСТ / 001</div><div class="video-grid">${videos.map((v,i)=>`<article class="video-card"><div class="video-mount"><button class="video-preview" data-video="${i}" aria-label="${esc(v.title)}${v.src?' — смотреть видео':' — открыть превью'}">${photo(v.poster,'(min-width: 900px) 22vw, 30vw')}<span class="video-number micro">${v.id}</span><span class="play-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M9 5 20 12 9 19Z"/></svg></span>${!v.src?'<span class="video-soon">СКОРО</span>':''}</button></div><h3>${esc(v.title)}</h3><p>${esc(v.category)}</p></article>`).join('')}</div></div><p class="work-bottom handwritten">маленькие истории, которые хочется досмотреть</p></div></section>`}
function Services(){return `<section class="services section" id="services"><div class="wrap">${label('05','Что я создаю')}<h2>От первого кадра<br>до «сохранить».</h2><div class="services-board"><figure class="services-center"><div class="viewfinder"><span class="micro">В КАДРЕ / ЛИЗА</span>${photo('beauty')}<span class="micro viewfinder-bottom">CONTENT WITH PERSONALITY</span></div><figcaption class="handwritten">сначала — идея.<br>потом — магия в кадре.</figcaption></figure><div class="service-note note-a paper"><span class="micro">01 / В ДВИЖЕНИИ</span><h3>${services[0]}</h3><p>${services[1]}</p><p>${services[6]}</p></div><div class="service-note note-b paper"><span class="micro">02 / В ГОЛОСЕ</span><h3>${services[2]}</h3><p>${services[3]}</p></div><div class="service-note note-c paper"><span class="micro">03 / В ДЕТАЛЯХ</span><h3>${services[4]}</h3><p>${services[5]}</p></div><div class="service-note note-d paper"><span class="micro">04 / В ВАШЕЙ ЛЕНТЕ</span><h3>${services[7]}</h3><p>${services[8]}</p></div></div></div></section>`}
function Gallery(){return `<section class="gallery section" id="gallery"><div class="wrap">${label('06','Фото-контент')}<div class="gallery-heading"><h2>Жизнь<br>между дублями.</h2><p class="handwritten">мои визуальные заметки</p></div><div class="photo-collage">${gallery.map((key,i)=>`<figure class="gallery-item gallery-item-${i+1}"><div class="gallery-mount"><button data-photo="${i}" aria-label="Открыть фото: ${esc(photos[key].alt)}">${photo(key,'(min-width: 900px) 30vw, 55vw')}</button>${[1,4].includes(i)?'<span class="tape" aria-hidden="true"></span>':''}<figcaption class="${[0,4].includes(i)?'handwritten':'micro'}">${['чуть больше меня','02 / BEAUTY NOTES','03 / ГОРОД','04 / EVERYDAY','в своём ритме','06 / FASHION DIARY'][i]}</figcaption></div></figure>`).join('')}<div class="gallery-note paper"><span class="micro">НА ПАМЯТЬ</span><p class="handwritten">не только как выглядит.<br>но и как чувствуется.</p></div></div></div></section>`}
function Contact(){return `<section class="contact section" id="contact"><div class="wrap"><div class="contact-letter paper"><div class="letter-top"><span class="micro">КОМУ: ВАШЕМУ БРЕНДУ<br>ОТ: ЛИЗЫ</span><span class="postage" aria-hidden="true">L.<small>CONTENT<br>WITH LOVE</small></span></div>${label('07','Связаться со мной')}<h2>Давайте создадим<br>что-то классное.</h2><div class="contact-body"><div><p>Готова к сотрудничеству с брендами в нишах бьюти, фешн и лайфстайл.</p><p>Если вам близка моя эстетика и формат контента — буду рада обсудить сотрудничество.</p><div class="social-links">${socials.map(s=>`<a href="${s.href}" ${s.href.startsWith('http')?'target="_blank" rel="noopener noreferrer"':''}><span class="micro">${s.name}</span><span>${s.label}</span></a>`).join('')}</div></div><figure class="contact-photo">${photo('portrait')}<figcaption class="handwritten">на связи,<br>Лиза</figcaption><span class="tape" aria-hidden="true"></span></figure></div><p class="letter-sign handwritten">начнём с вашего сообщения.</p></div><footer><a href="#home" class="wordmark">Л.</a><span class="micro">LIFESTYLE CREATOR & UGC</span><a href="#home">Наверх</a><button id="replay-intro">Открыть письмо</button></footer></div></section>`}
export function mountSections(target){target.innerHTML=[About(),Contents(),Niches(),Work(),Services(),Gallery(),Contact()].join('')}
